	[12816] = {
		id = 12816,
		skillName = '时空回溯',
		skillName_tw = '時空回溯',
		describe = '#C0xC0C0C0#为了连接遥远的过去，和遥远的未来~#C0x5B545B#\n#F10# \n#F40##L10#时间刻印：#L0#入场给自己和攻击最高的友方添加【时间刻印】，添加时记录目标的当前生命和怒气，受到致命伤害时消耗【时间刻印】触发【时空回溯】，免疫该伤害使生命和怒气回溯至记录值（不受治疗效果和怒气回复速度影响，不会使怒气低于当前值），驱散全部控制和负面效果，并提升#C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#最终伤害减免2回合 \n#F10# \n#F40##L10#预知未来：#L0#预先察觉未来的危险，完全躲避一次技能伤害（效果间隔5次受击）\n#F10# \n#F40##L10#时间波动：#L0#时拉比每次行动或回溯效果触发时，会产生【时间波动】，使友方随机精灵小技能冷却减少1回合和使敌方随机精灵小技能冷却延长1回合，并使敌方场上所有【种子炸弹】的引爆时间提前1回合\n#F10# \n#F40##L10#森之净化：#L0#友方全体每受到3个负面效果时，立即驱散己方阵营中的2个负面效果',
		describe_tw = '#C0xC0C0C0#為了連接遙遠的過去，和遙遠的未來~#C0x5B545B#\n#F10# \n#F40##L10#時間刻印：#L0#入場給自己和攻擊最高的友方添加【時間刻印】，添加時記錄目標的當前生命和怒氣，受到致命傷害時消耗【時間刻印】觸發【時空回溯】，免疫該傷害使生命和怒氣回溯至記錄值（不受治療效果和怒氣回復速度影響，不會使怒氣低於當前值），驅散全部控制和負面效果，並提升#C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#最終傷害減免2回合 \n#F10# \n#F40##L10#預知未來：#L0#預先察覺未來的危險，完全躲避一次技能傷害（效果間隔5次受擊）\n#F10# \n#F40##L10#時間波動：#L0#時拉比每次行動或回溯效果觸發時，會產生【時間波動】，使友方隨機精靈小技能冷卻減少1回合和使敵方隨機精靈小技能冷卻延長1回合，並使敵方場上所有【種子炸彈】的引爆時間提前1回合\n#F10# \n#F40##L10#森之淨化：#L0#友方全體每受到3個負面效果時，立即驅散己方陣營中的2個負面效果',
		describe_en = '#C0xC0C0C0#为了连接遥远的过去，和遥远的未来~#C0x5B545B#\n#F10# \n#F40#',
		starEffect = __data_t__starEffect[12816],
