	[19926] = {
		id = 19926,
		skillName = '星夜祈语',
		skillName_tw = '星夜祈語',
		describe = '#C0xB15BFF#<测试服>#C0x5B545B##L10#许愿笺：#L0#基拉祈回合结束后使用随机一种【许愿笺】进行祈愿，效果持续1回合\n#F10# \n#F40#①治愈之愿：治疗生命比例最低的目标50%已损失生命，并提升30%-#C0xEE0000#50%#C0x5B545B#伤害减免\n②流星之力：提升暴击最高的目标30%暴击和伤害加成，暴击时附带流星光束，对随机敌方目标造成基拉祈180%物攻伤害，并有#C0xFFB90F#100%#C0x5B545B#概率眩晕其1回合\n③神秘守护：优先令处于控制中的友方驱散并免疫可驱散的控制\n#F10# \n#F40#每祈愿一组上述三种许愿笺，基拉祈获得一层【星愿】并重置小技能冷却（星愿：增益效果，不可驱散，提升10%初始六维属性，30%流星伤害和10%孵化概率，上限5层）\n#F20# \n#F40##L10#沉睡之茧：#L0#受到致命伤害时，基拉祈会被封印到沉睡之茧中，期间不会进行祈愿。沉睡之茧继承基拉祈50%生命，攻击沉睡之茧的敌人会被流星反击，造成基拉祈180%物攻伤害，并有#C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B#概率被眩晕1回合\n#F20# \n#F40##L10#地之魔物：#L0#基拉祈死亡后，有30%概率孵化出一只“地之魔物”对全体敌方造成基拉祈400%-#C0xEE0000#1000%#C0x5B545B#的物攻伤害后消失',
		describe_tw = '#C0xB15BFF#<測試服>#C0x5B545B##L10#許願箋：#L0#基拉祈回合結束後使用隨機一種【許願箋】進行祈願，效果持續1回合\n#F10# \n#F40#①治癒之願：治療生命比例最低的目標50%已損失生命，並提升30%-#C0xEE0000#50%#C0x5B545B#傷害減免\n②流星之力：提升暴擊最高的目標30%暴擊和傷害加成，暴擊時附帶流星光束，對隨機敵方目標造成基拉祈180%物攻傷害，並有#C0xFFB90F#100%#C0x5B545B#概率眩暈其1回合\n③神秘守護：優先令處於控制中的友方驅散並免疫可驅散的控制\n#F10# \n#F40#每祈願一組上述三種許願箋，基拉祈獲得一層【星願】並重置小技能冷卻（星願：增益效果，不可驅散，提升10%初始六維屬性，30%流星傷害和10%孵化概率，上限5層）\n#F20# \n#F40##L10#沉睡之繭：#L0#受到致命傷害時，基拉祈會被封印到沉睡之繭中，期間不會進行祈願。沉睡之繭繼承基拉祈50%生命，攻擊沉睡之繭的敵人會被流星反擊，造成基拉祈180%物攻傷害，並有#C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B#概率被眩暈1回合\n#F20# \n#F40##L10#地之魔物：#L0#基拉祈死亡後，有30%概率孵化出一隻“地之魔物”對全體敵方造成基拉祈400%-#C0xEE0000#1000%#C0x5B545B#的物攻傷害後消失',
		starEffect = __data_t__starEffect[19926],
