	[32413] = {
		id = 32413,
		skillName = '冰封世界',
		skillName_tw = '冰封世界',
		skillName_en = 'Glaciate',
		describe = '酋雷姆于冰川之下苏醒，将整个世界化为狩猎场，获得2个【雪花】，场上没有【猎杀】目标则标记敌方后排随机一目标为【猎杀】目标2回合，并将场地变为【冰封世界】2回合，对目标造成#C0xE69900#400%物攻#C0x5B545B#+$(skillLevel*4*90)$的#C0xF13B54#物理伤害#C0x5B545B#；\n#F10# \n#F40##L10#冰封世界：#L0#所有敌方速度和双防降低30%，冰封世界下嘲讽【猎杀】目标（嘲讽：控制效果，使目标强制攻击自己），掠夺其25%初始双攻、150怒气和一个增益效果，并100%概率冰冻随机一个未被冰冻的其他敌方单位1回合；若本次必杀技导致【猎杀】目标死亡则立即给敌方后排重新添加一个【猎杀】标记',
		describe_tw = '酋雷姆於冰川之下蘇醒，將整個世界化為狩獵場，獲得2個【雪花】，場上沒有【獵殺】目標則標記敵方後排隨機一目標為【獵殺】目標2回合，並將場地變為【冰封世界】2回合，對目標造成#C0xE69900#400%物攻#C0x5B545B#+$(skillLevel*4*90)$的#C0xF13B54#物理傷害#C0x5B545B#；\n#F10# \n#F40##L10#冰封世界：#L0#所有敵方速度和雙防降低30%，冰封世界下嘲諷【獵殺】目標（嘲諷：控制效果，使目標強制攻擊自己），掠奪其25%初始雙攻、150怒氣和一個增益效果，並100%概率冰凍隨機一個未被冰凍的其他敵方單位1回合；若本次必殺技導致【獵殺】目標死亡則立即給敵方後排重新添加一個【獵殺】標記',
		describe_en = 'Kyurem turns the world into a hunting ground when it wakes up beneath the glaciers, gaining 2 【Snowflakes】. If there are no 【Hunted】 targets on the field, applies【Hunt】 to a random rear-line enemy and turn the field into 【Glaciate】for 2 rounds, dealing (#C0xE69900#400% P.ATK#C0x5B545B#+$(skillLevel*4*90)$) #C0xF13B54#P.DMG#C0x5B545B# to the target. \n#F10# \n#F40##L10#Glaciate: #L0#Reduces Speed, SP.DEF and P.DEF of all enemies by 30%, taunts 【Hunted】 foes in Glaciate. (Taunt: Control effect, forces the targets to attack the caster). Grabs 25% SP.ATK and P.ATK, 150 Rage and 1 buff from the target and freezes one random enemy. When a 【Hunted】 enemy faints, instantly grants 1 【Hunt】 to a rear-line enemy.',
		simDesc = '酋雷姆将大地冰封，届时，整个世界都将成为他的狩猎场',
		simDesc_tw = '酋雷姆將大地冰封，屆時，整個世界都將成為他的狩獵場',
		starEffect = __data_t__starEffect[32413],
		-- {11}
		starEffectDesc = '额外效果：冰封世界下攻击【猎杀】目标时邀战己方后排随机两个精灵一同普攻【猎杀】目标',
		starEffectDesc_tw = '額外效果：冰封世界下攻擊【獵殺】目標時邀戰己方後排隨機兩個精靈一同普攻【獵殺】目標',
		starEffectDesc_en = 'Extra effect: When it attacks a【Hunted】 target in 【Glaciate】, two random rear-line allies also deals basic attack to that target.',
		zawakeEffect = __data_t__zawakeEffect[32413],
		-- {79003}
		zawakeEffectDesc = '酋雷姆于冰川之下苏醒，将整个世界化为狩猎场，获得2个【雪花】，场上没有【猎杀】目标则标记敌方后排随机一目标为【猎杀】目标2回合，并将场地变为【冰封世界】2回合，对目标造成#C0xE69900#400%物攻#C0x5B545B#+$(skillLevel*4*90)$的#C0xF13B54#物理伤害#C0x5B545B#；\n#F10# \n#F40##L10#冰封世界：#L0#所有敌方速度和双防降低30%，冰封世界下嘲讽【猎杀】目标（嘲讽：控制效果，使目标强制攻击自己），掠夺其25%初始双攻、150怒气和一个增益效果，并100%概率冰冻随机一个未被冰冻的其他敌方单位1回合；若本次必杀技导致【猎杀】目标死亡则立即给敌方后排重新添加一个【猎杀】标记；若冰封世界期间【猎杀】目标死亡，酋雷姆会获得300怒气和一个雪花并永久获得掠夺的双攻效果',
